import { readFile, access, mkdir } from 'node:fs/promises';
import { resolve, basename } from 'node:path';
import { pathToFileURL, fileURLToPath } from 'node:url';

// Format/size optimization only. Product artwork and lettering are generated by imagegen.
// Usage: node scripts/import-product-images.mjs <reviewed-manifest.json> <sharp-entry.js>
const [manifestPath, sharpPath] = process.argv.slice(2);
if (!manifestPath || !sharpPath) throw new Error('Provide a reviewed image manifest and the installed sharp entry path');
const sharp = (await import(pathToFileURL(resolve(sharpPath)).href)).default;
const jobs = JSON.parse(await readFile(new URL('../data/product-image-prompts.json', import.meta.url), 'utf8'));
const allowed = new Set(jobs.map(job => job.filename));
const manifest = JSON.parse(await readFile(resolve(manifestPath), 'utf8'));
if (!Array.isArray(manifest)) throw new Error('Expected an array of reviewed image results');
const destination = fileURLToPath(new URL('../assets/products/', import.meta.url));
await mkdir(destination, { recursive: true });
let imported = 0;
for (const item of manifest) {
  if (item.status !== 'ready') continue;
  if (!allowed.has(item.filename) || basename(item.filename) !== item.filename) throw new Error('Unexpected image target');
  const output = resolve(destination, item.filename);
  try { await access(output); continue; } catch {}
  const source = resolve(item.sourcePath);
  const metadata = await sharp(source).metadata();
  if (!metadata.width || !metadata.height || Math.min(metadata.width, metadata.height) < 600) {
    throw new Error('Generated image is too small: ' + item.filename);
  }
  await sharp(source).rotate().resize({ width: 960, height: 960, fit: 'contain', background: '#ffffff' }).webp({ quality: 88, effort: 5 }).toFile(output);
  imported++;
  console.log('Imported ' + item.filename);
}
console.log(imported + ' new product images imported; existing assets preserved.');
